#!/usr/bin/env node
/** Builds siftei-kohen, peleti, mateh-yehonatan, yad-ephraim for siman 094 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import bh from './translations-094/baer-heitev.mjs';

const DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'translations-094');

function arr(s) {
  return `["${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"]`;
}

function esc(s) {
  return s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');
}

function writeSlug(name, obj) {
  const lines = ['export default {'];
  for (const [k, v] of Object.entries(obj)) {
    lines.push(`  '${k}': \`${esc(v)}\`,`);
  }
  lines.push('};');
  lines.push('');
  fs.writeFileSync(path.join(DIR, `${name}.mjs`), lines.join('\n'), 'utf8');
}

